 public void VerifyInterruptions(){worldTesting=true;data.World=new(){Automatic=false};data.Expeditions.Enabled=false;data.NaturalMobs=false;data.Volume=0;mobs.Clear();wolf=null;curiosity=90;energy=90;hunger=90;mischief=90;var report=new List<string>();
  foreach(var kind in new[]{WorldEventKind.Fishing,WorldEventKind.Treasure,WorldEventKind.BuildHouse,WorldEventKind.Cave,WorldEventKind.Prison,WorldEventKind.Portal,WorldEventKind.Ufo,WorldEventKind.YouTube}){CancelWorld();world.Clear();action=Act.Idle;vy=throwVx=0;respawnTime=0;heldItem=null;world.Queue(kind);UpdateWorld(.1f);if(world.Active?.Spec.Kind!=kind)throw new Exception("Resume fixture failed: "+kind);for(int i=0;i<45&&world.Busy;i++)UpdateWorld(.1f);var active=world.Active!;var id=active.Id;float time=active.Age;int phase=active.Phase;InterruptActivity();dragging=pressed=true;action=Act.Dragged;for(int i=0;i<30;i++)UpdateWorld(.1f);if(world.Busy||interruptedWorld?.Age!=time)throw new Exception("Interrupted event advanced: "+kind);dragging=pressed=false;action=Act.Idle;heldItem=null;vy=throwVx=0;x+=40;ResumeInterrupted(2);if(world.Active?.Id!=id||world.Active.Age!=time||world.Active.Phase!=phase)throw new Exception("Event restarted instead of resuming: "+kind);report.Add("PASS: "+kind+" resumes the same event ID, age and phase after interruption.");CancelWorld();world.Clear();}
  CancelWorld();world.Clear();action=Act.Idle;heldItem=null;vy=throwVx=0;forcedChaosResult=1;world.Queue(WorldEventKind.Casino);UpdateWorld(.1f);for(int i=0;i<60;i++)UpdateWorld(.1f);int dirt=data.Items["Dirt"];InterruptActivity();action=Act.Idle;ResumeInterrupted(2);for(int i=0;i<60&&world.Busy;i++)UpdateWorld(.1f);if(data.Items["Dirt"]!=dirt)throw new Exception("Resumed event granted reward twice");report.Add("PASS: resuming after the reward phase does not duplicate inventory rewards.");CancelWorld();world.Clear();
  action=Act.Walk;age=2;duration=12;InterruptActivity();action=Act.Dance;ResumeInterrupted(10);if(interruptedOrdinary!=Act.Walk)throw new Exception("Temporary dance discarded original behavior");action=Act.Idle;ResumeInterrupted(1);if(action!=Act.Walk||age!=2||duration!=12)throw new Exception("Ordinary task did not resume");report.Add("PASS: ordinary behavior resumes after a temporary interaction.");
  data.Expeditions.Enabled=true;expedition.Go(ExpeditionState.Returning);expedition.Tick(1.25,true,data.Expeditions);double tripAge=expedition.Age;InterruptExpedition();UpdateExpedition(10);if(expedition.Age!=tripAge||expedition.State!=ExpeditionState.Returning)throw new Exception("Interrupted trip lost progress");action=Act.Idle;heldItem=null;ResumeInterrupted(2);if(interruptedExpedition||expedition.Age!=tripAge)throw new Exception("Trip failed to resume");CancelExpedition();report.Add("PASS: interrupted meme trip retains its state and delivery progress.");
  data.Expeditions.Enabled=false;action=Act.Idle;vy=throwVx=0;world.Queue(WorldEventKind.Casino);UpdateWorld(.1f);InterruptActivity();CancelWorld();action=Act.Idle;ResumeInterrupted(5);if(world.Busy||interruptedWorld!=null)throw new Exception("Explicit cancel resumed the event");report.Add("PASS: explicit Cancel remains permanent.");Directory.CreateDirectory("artifacts");File.WriteAllLines("artifacts/interruption-tests.txt",report);
 }
